```go
// Package macaroon implements attenuable bearer tokens (macaroons) with
// first-party caveats, third-party discharge caveats and HMAC-SHA256
// signature chaining.
//
// Signature scheme (all values are 32 bytes):
//
//	sig0   = HMAC(makeKey(rootKey), id)
//	sig_i  = HMAC(sig_{i-1}, caveatId)                       first-party
//	sig_i  = HMAC2(sig_{i-1}, verificationId, caveatId)      third-party
//	bind   = HMAC2(0, primarySig, dischargeSig)              discharge binding
//
// where HMAC2(k, a, b) = HMAC(k, HMAC(k,a) || HMAC(k,b)) and
// makeKey(vk) = HMAC("macaroons-key-generator", vk). This mirrors the
// libmacaroons / gopkg.in/macaroon.v2 construction.
package macaroon

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"errors"
	"fmt"
)

const (
	keyLen  = 32
	hashLen = sha256.Size
	// maxDischargeDepth bounds recursion as defence in depth against long
	// non-cyclic chains; cycles are already rejected by the used-set.
	maxDischargeDepth = 64
)

var (
	errInvalidSignature = errors.New("macaroon: invalid signature")
	keyGen              = []byte("macaroons-key-generator")
	zeroKey             [keyLen]byte
)

// Macaroon is an attenuable bearer token. Macaroons are mutable; Clone
// before branching an attenuation chain.
type Macaroon struct {
	location string
	id       []byte
	caveats  []Caveat
	sig      [hashLen]byte
}

// Caveat is a first- or third-party restriction. For first-party, only Id
// (the predicate) is set. For third-party, Id is the discharge lookup id
// (must equal the discharge macaroon's Id) and VerificationId seals the
// discharge root key under the signature that preceded this caveat.
type Caveat struct {
	Id             []byte
	VerificationId []byte
	Location       string
}

// New mints a root macaroon from a secret root key.
func New(rootKey, id []byte, location string) *Macaroon {
	m := &Macaroon{location: location, id: append([]byte(nil), id...)}
	k := makeKey(rootKey)
	m.sig = keyedHash(&k, m.id)
	return m
}

// Clone returns a deep copy of m.
func (m *Macaroon) Clone() *Macaroon {
	m1 := *m
	m1.id = append([]byte(nil), m.id...)
	m1.caveats = make([]Caveat, len(m.caveats))
	for i, c := range m.caveats {
		m1.caveats[i] = Caveat{
			Id:             append([]byte(nil), c.Id...),
			VerificationId: append([]byte(nil), c.VerificationId...),
			Location:       c.Location,
		}
	}
	return &m1
}

func (m *Macaroon) Id() []byte        { return append([]byte(nil), m.id...) }
func (m *Macaroon) Location() string  { return m.location }

// Signature returns a copy of the current signature.
func (m *Macaroon) Signature() []byte {
	s := make([]byte, hashLen)
	copy(s, m.sig[:])
	return s
}

// Caveats returns a deep copy of the caveat slice.
func (m *Macaroon) Caveats() []Caveat {
	cs := make([]Caveat, len(m.caveats))
	for i, c := range m.caveats {
		cs[i] = Caveat{
			Id:             append([]byte(nil), c.Id...),
			VerificationId: append([]byte(nil), c.VerificationId...),
			Location:       c.Location,
		}
	}
	return cs
}

// AddFirstPartyCaveat appends a predicate the target service must satisfy.
func (m *Macaroon) AddFirstPartyCaveat(condition []byte) {
	m.caveats = append(m.caveats, Caveat{Id: append([]byte(nil), condition...)})
	m.sig = keyedHash(&m.sig, condition)
}

// AddThirdPartyCaveat appends a caveat discharged by a third party holding
// sharedKey. caveatId must be the Id of the discharge macaroon.
func (m *Macaroon) AddThirdPartyCaveat(sharedKey, caveatId []byte, loc string) error {
	dischargeRootKey := makeKey(sharedKey)
	vid, err := encrypt(&m.sig, &dischargeRootKey)
	if err != nil {
		return fmt.Errorf("macaroon: sealing discharge key: %w", err)
	}
	m.caveats = append(m.caveats, Caveat{
		Id:             append([]byte(nil), caveatId...),
		VerificationId: vid,
		Location:       loc,
	})
	m.sig = keyedHash2(&m.sig, vid, caveatId)
	return nil
}

// Bind ties a discharge to the final signature of its primary, defeating
// replanting onto a sibling token.
func (m *Macaroon) Bind(primarySig []byte) {
	m.sig = bindForRequest(primarySig, m.sig[:])
}

// makeKey derives a fixed-length key from an arbitrary-length root key.
func makeKey(variableKey []byte) [keyLen]byte {
	h := hmac.New(sha256.New, keyGen)
	h.Write(variableKey)
	var k [keyLen]byte
	copy(k[:], h.Sum(nil))
	return k
}

// keyedHash is HMAC-SHA256(key, text).
func keyedHash(key *[keyLen]byte, text []byte) [hashLen]byte {
	h := hmac.New(sha256.New, key[:])
	h.Write(text)
	var sum [hashLen]byte
	copy(sum[:], h.Sum(nil))
	return sum
}

// keyedHash2 is HMAC(k, HMAC(k,a) || HMAC(k,b)).
func keyedHash2(key *[keyLen]byte, a, b []byte) [hashLen]byte {
	ha := keyedHash(key, a)
	hb := keyedHash(key, b)
	var data [hashLen * 2]byte
	copy(data[:hashLen], ha[:])
	copy(data[hashLen:], hb[:])
	return keyedHash(key, data[:])
}

// bindForRequest binds a discharge signature to a primary signature. The
// zero-key prefix domain-separates it; comparison uses hmac.Equal.
func bindForRequest(primarySig, dischargeSig []byte) [hashLen]byte {
	if hmac.Equal(primarySig, dischargeSig) {
		var s [hashLen]byte
		copy(s[:], dischargeSig)
		return s
	}
	return keyedHash2(&zeroKey, primarySig, dischargeSig)
}

// encrypt seals a 32-byte discharge root key under the macaroon signature.
func encrypt(key *[keyLen]byte, plaintext *[hashLen]byte) ([]byte, error) {
	block, err := aes.NewCipher(key[:])
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return nil, err
	}
	out := make([]byte, len(nonce))
	copy(out, nonce)
	return gcm.Seal(out, nonce, plaintext[:], nil), nil
}

// decrypt reverses encrypt; it authenticates the ciphertext so tampering
// fails closed instead of yielding a wrong root key.
func decrypt(key *[keyLen]byte, ciphertext []byte) ([hashLen]byte, error) {
	var out [hashLen]byte
	block, err := aes.NewCipher(key[:])
	if err != nil {
		return out, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return out, err
	}
	ns := gcm.NonceSize()
	if len(ciphertext) < ns+gcm.Overhead() {
		return out, errors.New("macaroon: verification id too short")
	}
	nonce, ct := ciphertext[:ns], ciphertext[ns:]
	pt, err := gcm.Open(nil, nonce, ct, nil)
	if err != nil {
		return out, errors.New("macaroon: verification id authentication failed")
	}
	if len(pt) != hashLen {
		return out, errors.New("macaroon: discharge key has wrong length")
	}
	copy(out[:], pt)
	return out, nil
}
