`verify.go`:

```go
package macaroon

import (
	"bytes"
	"crypto/hmac"
	"fmt"
)

// Verification is two-phase:
//  1. authenticate recomputes every HMAC chain, resolves and binds every
//     discharge, rejects cycles/duplicates and collects first-party caveat
//     conditions in traversal order without invoking user code.
//  2. conditions are handed to the caller's check in that exact order.
//
// MAC check before policy check means a chosen-caveat adversary can never
// make the verifier evaluate attacker-influenced predicates on an
// unauthenticated token.
type verificationContext struct {
	used       []bool
	discharges []*Macaroon
	primarySig []byte
	conditions []string
}

// Verify authenticates m against rootKey, resolves discharges, then
// evaluates every first-party caveat with check (non-nil error = deny).
// Every supplied discharge must be used exactly once. Conditions are
// evaluated in attenuation order, depth-first into discharges.
func (m *Macaroon) Verify(rootKey []byte, check func(condition string) error, discharges []*Macaroon) error {
	if check == nil {
		check = func(string) error { return nil }
	}
	vc := &verificationContext{
		discharges: discharges,
		used:       make([]bool, len(discharges)),
		primarySig: m.Signature(),
	}
	k := makeKey(rootKey)
	if err := vc.authenticate(m, 0, 0, &k); err != nil {
		return err
	}
	for i, used := range vc.used {
		if !used {
			return fmt.Errorf("macaroon: discharge macaroon %q was not used", vc.discharges[i].id)
		}
	}
	for _, cond := range vc.conditions {
		if err := check(cond); err != nil {
			return err
		}
	}
	return nil
}

func (vc *verificationContext) authenticate(m *Macaroon, index, depth int, rootKey *[keyLen]byte) error {
	if depth > maxDischargeDepth {
		return fmt.Errorf("macaroon: discharge chain exceeds depth %d", maxDischargeDepth)
	}
	caveatSig := keyedHash(rootKey, m.id)
	for i, cav := range m.caveats {
		if len(cav.VerificationId) > 0 {
			// Discharge key was sealed under the signature preceding
			// this caveat, so decrypt before advancing.
			dischargeKey, err := decrypt(&caveatSig, cav.VerificationId)
			if err != nil {
				return fmt.Errorf("macaroon: caveat %d: cannot recover discharge key: %w", i, err)
			}
			dm, di, err := vc.findDischarge(cav.Id)
			if err != nil {
				return err
			}
			if err := vc.authenticate(dm, di+1, depth+1, &dischargeKey); err != nil {
				return err
			}
			caveatSig = keyedHash2(&caveatSig, cav.VerificationId, cav.Id)
			continue
		}
		caveatSig = keyedHash(&caveatSig, cav.Id)
		vc.conditions = append(vc.conditions, string(cav.Id))
	}
	if index > 0 {
		caveatSig = bindForRequest(vc.primarySig, caveatSig[:])
	}
	// Constant-time comparison: never leak how many leading bytes matched.
	if !hmac.Equal(caveatSig[:], m.sig[:]) {
		return errInvalidSignature
	}
	return nil
}

// findDischarge returns the discharge whose id equals id and marks it used.
// The used-set makes cyclic/self-referential graphs terminate.
func (vc *verificationContext) findDischarge(id []byte) (*Macaroon, int, error) {
	for i, dm := range vc.discharges {
		if dm == nil || !bytes.Equal(dm.id, id) {
			continue
		}
		if vc.used[i] {
			return nil, 0, fmt.Errorf("macaroon: discharge %q used more than once (cycle or duplicate caveat)", id)
		}
		vc.used[i] = true
		return dm, i, nil
	}
	return nil, 0, fmt.Errorf("macaroon: no discharge macaroon for caveat %q", id)
}
