```go
func FuzzNoTamperAccepted(f *testing.F) {
	f.Add([]byte("root"), []byte("id"), []byte("a=1"))
	f.Fuzz(func(t *testing.T, root, id, cond []byte) {
		m := New(root, id, "loc")
		m.AddFirstPartyCaveat(cond)
		if m.Verify(root, func(string) error { return nil }, nil) != nil {
			t.Fatal("freshly minted macaroon failed")
		}
		for i := range m.sig {
			c := m.Clone()
			c.sig[i] ^= 1
			if c.Verify(root, func(string) error { return nil }, nil) == nil {
				t.Fatalf("tampered signature accepted at byte %d", i)
			}
		}
	})
}
