## 4. Directly usable recipe

```go
root := []byte("bank-root-key")
shared := []byte("shared-with-auth-service")

m := macaroon.New(root, []byte("invoice/42"), "bank.example")
_ = m.AddThirdPartyCaveat(shared, []byte("auth/verified-email"), "auth.example")
m.AddFirstPartyCaveat([]byte("role=user"))

d := macaroon.New(shared, []byte("auth/verified-email"), "auth.example")
d.AddFirstPartyCaveat([]byte("email=verified"))
d.Bind(m.Signature())

err := m.Verify(root, func(condition string) error {
	// Evaluate condition against trusted request state; return an error to deny.
	return nil
}, []*macaroon.Macaroon{d})
```
